        }

        function getNewImageUrl(e, t, a) {
            e = e.split("?");
            let n = e[0];
            var r, e = e[1];
            return a && (r = getExtension(n), n += "." + a + "." + r), t && (n += ".bv.webp"), e && (n += "?" + e), n
        }

        function isOurCdnImage(e) {
            return !!e.includes(BV_CDN_URL)
        }

        function canChangeUrl(e) {
            return "svg" !== getExtension(e) && !e.includes("data:image") && !!isOurCdnImage(e)
        }

        function handleNodeElements(e, t, n, r) {
            e.forEach(a => {
                t.forEach(t => {
                    if (flag = !1, a.hasAttribute(t)) {
                        attr_val = a.getAttribute(t), new_val = "";
                        let e = attr_val.split(",");
                        e.forEach(e => {
                            let t = e.trim().split(" ");
                            var a = t.shift();
                            if (flag ? new_val += "," : flag = !0, isValidUrl(a) && isImage(a))
                                if (canChangeUrl(a)) {
                                    let e = getNewImageUrl(a, n, r);
                                    new_val += [e].concat(t).join(" ")
                                } else new_val += e;
                            else new_val += e
                        }), a.setAttribute(t, new_val)
                    }
                })
            })
        }

        function handleTagWithStyle(e, r, l) {
            e.forEach(t => {
                var a = t.getAttribute("bv-style-url");
                if (a && isValidUrl(a) && isImage(a) && canChangeUrl(a)) {
                    var n = getNewImageUrl(a, r, l);
                    let e = t.getAttribute("bv-data-style");
                    new_style_val = e.replace(a, n), t.setAttribute("bv-data-style", new_style_val)
                }
            })
        }
        let webp_status = isWebpSupported(),
            device_name = getImageDeviceName(),
            img_tags = document.querySelectorAll(".bv-tag-attr-replace"),
            tag_elements_with_style = (handleNodeElements(img_tags, IMAGE_URL_ATTRIBUTES, webp_status, device_name), document.querySelectorAll(".bv-style-attr-replace"));
        handleTagWithStyle(tag_elements_with_style, webp_status, device_name);
    </script>

